/*!
 * /bp/socket.io.min.js — 面板通道 client（本地回环实现）
 * 契约 §2：socket.io client 4.7.4 的等效 API 子集
 *
 * 线上环境请用官方 socket.io-client 4.7.4 构建产物覆盖本文件；
 * 本文件为离线/静态托管环境下 connector 的等价实现：
 *   io(host, {path, transports}) → socket
 *   socket.on(event, fn) / socket.emit(event, payload) / socket.connected
 *
 * 行为：连接 -> connect 事件；emit 走 WebSocket 帧，失败静默降级，
 *       保证「面板不在线时结账页仍然可用」（契约 11：降级运行不报错）。
 */
(function (global) {
  'use strict';

  var VERSION = '4.7.4';

  function Emitter() {
    this._handlers = {};
  }
  Emitter.prototype.on = function (ev, fn) {
    (this._handlers[ev] || (this._handlers[ev] = [])).push(fn);
    return this;
  };
  Emitter.prototype.once = function (ev, fn) {
    var self = this;
    function wrap() { self.off(ev, wrap); fn.apply(null, arguments); }
    return this.on(ev, wrap);
  };
  Emitter.prototype.off = function (ev, fn) {
    if (!this._handlers[ev]) return this;
    if (!fn) { this._handlers[ev] = []; return this; }
    this._handlers[ev] = this._handlers[ev].filter(function (f) { return f !== fn; });
    return this;
  };
  Emitter.prototype.emitLocal = function (ev, payload) {
    var list = this._handlers[ev] || [];
    for (var i = 0; i < list.length; i++) {
      try { list[i](payload); } catch (e) {}
    }
    return this;
  };

  function Socket(host, opts) {
    Emitter.call(this);
    this.host = host || '';
    this.path = (opts && opts.path) || '/socket.io/';
    this.connected = false;
    this.id = null;
    this._queue = [];
    this._ws = null;
    this._retry = 0;
    var self = this;
    // 异步连上，避免阻塞首屏
    setTimeout(function () { self._connect(); }, 0);
  }
  Socket.prototype = Object.create(Emitter.prototype);
  Socket.prototype.constructor = Socket;

  Socket.prototype._url = function () {
    try {
      var u = new URL(this.host, location.href);
      u.protocol = u.protocol === 'https:' ? 'wss:' : 'ws:';
      u.pathname = this.path.replace(/\/$/, '') + '/';
      u.search = 'EIO=4&transport=websocket';
      return u.toString();
    } catch (e) {
      return this.host;
    }
  };

  Socket.prototype._connect = function () {
    var self = this;
    var url = this._url();
    var opened = false;
    try {
      this._ws = new WebSocket(url);
    } catch (e) {
      this._offline();
      return;
    }
    this._ws.onopen = function () {
      opened = true;
      self.connected = true;
      self.id = String(Math.random()).slice(2, 12);
      self.emitLocal('connect');
      while (self._queue.length) {
        try { self._ws.send(self._queue.shift()); } catch (e) {}
      }
    };
    this._ws.onmessage = function (ev) {
      var raw = ev.data;
      if (typeof raw !== 'string') return;
      // engine.io 帧：40 = namespace connect, 42 = event
      if (raw.indexOf('42') === 0) {
        try {
          var arr = JSON.parse(raw.slice(2));
          if (Array.isArray(arr) && arr.length) self.emitLocal(arr[0], arr[1]);
        } catch (e) {}
      } else if (raw === '40') {
        self.emitLocal('connect');
      }
    };
    this._ws.onclose = function () {
      self.connected = false;
      self.emitLocal('disconnect', 'transport close');
      if (opened) self._scheduleReconnect();
    };
    this._ws.onerror = function () {
      if (!opened) self._offline();
    };
  };

  Socket.prototype._offline = function () {
    // 面板不可达：静默降级，connector 继续以本地状态工作
    this.connected = false;
    this.emitLocal('connect_error', new Error('panel unreachable'));
  };

  Socket.prototype._scheduleReconnect = function () {
    var self = this;
    var delay = Math.min(30000, 1000 * Math.pow(2, Math.min(this._retry++, 5)));
    setTimeout(function () { self._connect(); }, delay);
  };

  Socket.prototype.emit = function (ev) {
    var args = [].slice.call(arguments, 1);
    var frame = '42' + JSON.stringify([ev].concat(args));
    if (this.connected && this._ws && this._ws.readyState === 1) {
      try { this._ws.send(frame); return this; } catch (e) {}
    }
    if (this._queue.length < 256) this._queue.push(frame);
    return this;
  };

  Socket.prototype.close = function () {
    this.connected = false;
    try { this._ws && this._ws.close(); } catch (e) {}
    return this;
  };

  Socket.prototype.disconnect = Socket.prototype.close;

  function io(host, opts) { return new Socket(host, opts); }
  io.version = VERSION;
  io.connect = io;
  io.Socket = Socket;

  global.io = io;
})(typeof window !== 'undefined' ? window : this);
